    # node i + m represents negative literal -x_{i+1}
    num_nodes = 2 * m
    adj = [[] for _ in range(num_nodes)]

    def lit_to_node(lit):
        """Convert literal value (positive or negative) to node index."""
        if lit > 0:
            return lit - 1  # 0-indexed positive
        else:
            return m + (-lit) - 1  # 0-indexed negative

    def node_to_lit(node):
        """Convert node index back to literal value."""
        if node < m:
            return node + 1  # positive literal x
        else:
            return -(node - m + 1)  # negative literal -x

    def neg_node(node):
        """Get the node index representing the negation of this node's literal."""
        if node < m:
            return m + node
        else:
            return node
        # Alternatively: return node ^ m

    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        clause = parts[1:]

        # For clause (l1 OR l2 OR ... OR lk), add implications:
        # For any literal li in the clause, if li is false, then at least one other literal must be true.
        # So: neg(li) -> lj for all j != i
        for i_clause in range(k):
            u = clause[i_clause]
            u_node = lit_to_node(u)
            for j_clause in range(k):
                v = clause[j_clause]
                if i_clause != j_clause:
                    v_node = lit_to_node(v)
                    adj[u_node].append(v_node)

    # Tarjan's algorithm for SCC
    ids = [-1] * num_nodes
    low = [0] * num_nodes
    on_stack = [False] * num_nodes
    stack = []
    scc = [-1] * num_nodes
    scc_count = 0
    timer = [0]

    def dfs(at):
        ids[at] = low[at] = timer[0]
        timer[0] += 1
        stack.append(at)
        on_stack[at] = True

        for to in adj[at]:
            if ids[to] == -1:
                dfs(to)
                low[at] = min(low[at], low[to])
            elif on_stack[to]:
                low[at] = min(low[at], ids[to])

        if ids[at] == low[at]:
            while stack:
                node = stack.pop()
                on_stack[node] = False
                scc[node] = scc_count
                if node == at:
                    break
            scc_count += 1

    for i in range(num_nodes):
        if ids[i] == -1:
            dfs(i)

    # Check satisfiability: x and -x should not be in the same SCC
    possible = True
    for i in range(m):
        pos_node = i
        neg_node = i + m
        if scc[pos_node] == scc[neg_node]:
            return "NO"

    # Construct satisfying assignment
    # Process SCCs in reverse topological order (higher scc_id first)
    assignment = [0] * m
    for cid in range(scc_count - 1, -1, -1):
        for node in range(num_nodes):
            if scc[node] == cid:
                lit = node_to_lit(node)
                x_idx = abs(lit) - 1  # 0-indexed variable

                if lit > 0:
                    # positive literal in this SCC
                    assignment[x_idx] = 1
                else:
                    # negative literal in this SCC
                    assignment[x_idx] = 0

    return f"YES\n{chr(48).join(map(str, assignment))}"

