def solution(input_str):
    """
    Determines if all stones can be removed from piles, optionally swapping
    one adjacent pair once.
    """
    data = input_str.split()
    if not data:
        return ''

    it = iter(data)
    try:
        t = int(next(it))
    except StopIteration:
        return ''

    result = []

    for _ in range(t):
        try:
            n = int(next(it))
            a = [int(next(it)) for _ in range(n)]

            def check(arr):
                """Check if all stones can be removed from this array."""
                if len(arr) == 0:
                    return True
                if arr[0] < 0:  # Negative stones at start - invalid
                    return False
                if len(arr) == 1:
                    return arr[0] == 0

                carry = arr[0]
                for i in range(1, len(arr)):
                    if carry > arr[i]:
                        return False
                    carry = carry - arr[i]
                return carry == 0

            original = a[:]
            if check(original):
                result.append("YES")
            else:
                possible = False
                for i in range(n - 1):
                    # Swap adjacent elements at positions i and i+1
                    arr_to_check = original[:]
                    arr_to_check[i], arr_to_check[i + 1] = arr_to_check[i + 1], arr_to_check[i]
                    if check(arr_to_check):
                        possible = True
                        break
                result.append("YES" if possible else "NO")
        except StopIteration:
            break

    return '\n'.join(result)


