from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]

    def add_edge(self, u, v, cap):
        self.graph[u].append([v, cap, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])

    def bfs(self, s, t, dist):
        for i in range(self.n):
            dist[i] = -1
        dist[s] = 0
        q = deque([s])

        while q:
            u = q.popleft()
            for v, cap, idx in self.graph[u]:
                if cap > 0 and dist[v] < 0:
                    dist[v] = dist[u] + 1
                    q.append(v)

        return dist[t] >= 0

    def dfs(self, u, t, flow, gr, dist):
        if u == t or flow == 0:
            return flow
        for i in range(gr[u], len(self.graph[u])):
            gr[u][i] = i
            v, cap, idx = self.graph[u][i]
            if cap > 0 and dist[v] == dist[u] + 1:
                pushed = self.dfs(v, t, min(flow, cap), gr, dist)
                if pushed > 0:
                    self.graph[u][i][1] -= pushed
                    self.graph[idx][1] += pushed
                    return pushed
        return 0

    def max_flow(self, s, t):
        flow = 0
        while True:
            dist = [-1] * self.n
            if not self.bfs(s, t, dist):
                break
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr, dist)
                if pushed == 0:
                    break
                flow += pushed
        return flow

def get_prime_factors_with_count(n):
    if n <= 1:
        return {}
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

