    MOD = 10**9 + 7

    # Base case: visiting exactly 1 planet
    if k == 1:
        return str(n % MOD)

    # For k planets, we iterate through each starting planet
    # and use DFS with memoization to count valid paths
    # State: (current_planet, visited_mask)
    # Since k <= 12, we can track visited as bitmask of position relative to start

    memo = {}

    def dfs(current, visited_mask, steps_left):
        """
        Count ways to complete the path from current planet
        with steps_left planets to visit total
        visited_mask tracks which planets (relative to current) are already visited
        """
        if steps_left == 0:
            return 1

        state = (current, visited_mask)
        if state in memo:
            return memo[state]

        total = 0
        # Next planet y must be in [1, current + m] and not visited
        # Since k is small, we can safely iterate
        for next_p in range(1, min(n, current + m) + 1):
            if next_p not in visited_mask:
                total = (total + dfs(next_p, visited_mask | (1 << (next_p - 1)), steps_left - 1)) % MOD

        memo[state] = total
        return total

    result = 0
    for start in range(1, n + 1):
        result = (result + dfs(start, (1 << (start - 1)), k - 1)) % MOD

    return str(result)

def inverse_permutation(row):
    n = len(row)
    inv = [0] * n
    for pos, val in enumerate(row):
        inv[val - 1] = pos + 1
    return inv

def process_R(matrix, n):
    """Shift all columns to the right."""
    for i in range(n):
        last = matrix[i][-1]
        matrix[i] = [last] + matrix[i][:-1]

def process_L(matrix, n):
    """Shift all columns to the left."""
    for i in range(n):
        first = matrix[i][0]
        matrix[i] = matrix[i][1:] + [first]

def process_D(matrix, n):
    """Shift all rows down."""
    temp_row = matrix[0]
    for i in range(n - 1):
        matrix[i] = matrix[i + 1]
    matrix[n - 1] = temp_row

def process_U(matrix, n):
    """Shift all rows up."""
    temp_row = matrix[n - 1]
    for i in range(n - 1, 0, -1):
        matrix[i] = matrix[i - 1]
    matrix[0] = temp_row

def process_I(matrix, n):
    """Invert each row."""
    for i in range(n):
        matrix[i] = inverse_permutation(matrix[i])

def process_C(matrix, n):
    """Invert each column."""
    new_matrix = [[0] * n for _ in range(n)]
    for j in range(n):
        col = [matrix[i][j] for i in range(n)]
        col_inv = [0] * n
        for pos, val in enumerate(col):
            col_inv[val - 1] = pos + 1
        for i in range(n):
            new_matrix[i][j] = col_inv[matrix[i][j] - 1]
    return new_matrix

