            # Check if all prime factors of b are coprime with used factors
            conflict = False
            for pf in prime_factors[b]:
                if pf in used_factors:
                    conflict = True
                    break

            if not conflict:
                current_b.append(b)
                new_factors = set(used_factors)
                new_factors.update(prime_factors[b])
                backtrack(idx + 1, current_b, new_factors)
                current_b.pop()

    backtrack(0, [], set())

    if best_result:
        return ' '.join(map(str, best_result)) + '\n'
    return ''

