from collections import deque

def solution(input_str):
    """
    Find the minimum number of operations to reduce n to 0,
    where each operation subtracts a digit from the current number.
    """
    input_str = input_str.strip()
    if not input_str:
        return "0\n"

    parts = input_str.split()
    if not parts:
        return "0\n"

    try:
        n = int(parts[0])
    except ValueError:
        return "0\n"

    if n == 0:
        return "0\n"

    # BFS to find minimum operations
    visited = {n}
    queue = deque([n])
    level = 0

    while queue:
        # Process all nodes at current level
        level_size = len(queue)
        for _ in range(level_size):
            current = queue.popleft()

            # Try subtracting each digit present in the current number
            for d in str(current):
                d_int = int(d)
                if d_int == 0:
                    continue
                next_num = current - d_int

                # If we reached 0, return the number of operations
                if next_num == 0:
                    return str(level + 1) + "\n"

                # Add unvisited states to queue
                if next_num not in visited:
                    visited.add(next_num)
                    queue.append(next_num)

        level += 1

    return "0\n"

from collections import defaultdict
import itertools

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())

    phone_numbers = []
    for line in lines[1:]:
        if not line:
            continue
        parts = line.split()
        if len(parts) >= 2:
            s, m = parts[0], int(parts[1])
            phone_numbers.append((s, m))

    if k == 0 or not phone_numbers:
        return str(sum(len(s) * m for s, m in phone_numbers))

    # Calculate default cost (if no speed dial buttons used)
    default_cost = sum(len(s) * m for s, m in phone_numbers)

    # Build trie and collect all nodes
    trie = {}

    # For each node in trie, store:
    # - count: total frequency of phone numbers passing through this node
    # - length: length of the prefix this node represents
    class TrieNode:
        def __init__(self):
            self.children = {}
            self.freq = 0
            self.depth = 0  # Depth in trie = length of prefix
            self.index = 0

    root = TrieNode()
    root.index = 0

    # Insert all phone numbers into trie
    for s_i, m_i in phone_numbers:
        node = root
        for char in s_i:
            if char not in node.children:
                node.children[char] = TrieNode()
                node.children[char].index = len(node.children)
            node = node.children[char]
        node.freq += m_i

    # Collect all nodes with their info
    nodes = []  # List of (node_index, freq, length)

    def collect(node, depth, index):
        nonlocal nodes
        if node:
            nodes.append((index, node.freq, depth))
            for child in node.children.values():
                collect(child, depth + 1, child.index)

    collect(root, 0, 0)

    if not nodes:
        return str(default_cost)

    # Try selecting up to k nodes from trie
    # Use DP approach

    # For each node in trie, precompute: if we select this node, 
    # we get depth * total_freq_saved where total_freq_saved = freq - freq_of_deeper_selected_nodes

    # Since this is complex, let's use a simpler enumeration with pruning

    # Collect all unique prefixes that match at least one phone number
    all_prefixes = set()
    for s, m in phone_numbers:
        for i in range(1, len(s) + 1):
            all_prefixes.add(s[:i])

    all_prefixes = list(all_prefixes)

    # For each phone number, map which prefixes it can match
    phone_prefix_map = []
    for s_i, m_i in phone_numbers:
        phone_prefix_map.append((s_i, m_i, [(p, len(p)) for p in all_prefixes if s_i.startswith(p)]))

    # If k is small, use enumeration with pruning
    # Since k <= 10 and total unique prefixes <= 500, we can try combinations

    # Sort prefixes by potential benefit (length * total matching frequency)
    prefix_benefits = []
    prefix_dict = {p: 0 for p in all_prefixes}

    for s_i, m_i, prefixes in phone_prefix_map:
        for p, f_len in prefixes:
            prefix_dict[p] += m_i

    prefix_with_lengths = [(p, prefix_dict[p], len(p)) for p in all_prefixes]

    # Calculate max savings directly
    def calculate_savings(selected_prefixes):
        if not selected_prefixes:
            return 0
        savings = 0
        for s_i, m_i, possible in phone_prefix_map:
            # Find longest matching selected prefix
            best_len = 0
            for p, f_len in sorted(possible, key=lambda x: x[1], reverse=True):
                if p in selected_prefixes:
                    best_len = f_len
                    break
            savings += best_len * m_i
        return savings

    max_savings = 0

    # We need to select up to k prefixes to maximize savings
    # Try different combinations
    for r in range(1, min(k, len(all_prefixes)) + 1):
        # Enumerate combinations
        for combo in itertools.combinations(all_prefixes, r):
            # Calculate savings
            current_savings = calculate_savings(set(combo))
            if current_savings > max_savings:
                max_savings = current_savings

    # Also consider selecting fewer than k prefixes (already covered by range)
    # But we should also consider: not using all k (which is OK since we resume from r=1)

    min_cost = default_cost - max_savings

    return str(min_cost)

